 "A save is still going. Leaving now could lose it.": "Aún se está guardando. Si sales ahora, podrías perderlo.",
 "A section you add starts on this scheme.": "Una sección que añadas empieza con este esquema.",
 "A segment": "Un segmento",
 "A shipping profile is a group of products that ship the same way. Every product starts in the General profile.": "Un perfil de envío es un grupo de productos que se envían de la misma forma. Todos los productos empiezan en el perfil General.",
 "A shipping rate for where you sell, or local pickup.": "Una tarifa de envío para donde vendes, o recogida local.",
