 "An email you start and do not send yet is kept here.": "Un correo que empiezas y aún no envías se guarda aquí.",
 "An empty React project.": "Un proyecto React vacío.",
 "An empty repository works best. If the branch is protected on GitHub, type a new one, such as storelib, and Storelib makes it.": "Lo mejor es un repositorio vacío. Si la rama está protegida en GitHub, escribe una nueva, como storelib, y Storelib la crea.",
 "An error occurred": "Se produjo un error",
 "An error occurred while saving. Please try again.": "Se produjo un error al guardar. Inténtalo de nuevo.",
 "An error occurred. Please try again.": "Se produjo un error. Inténtalo de nuevo.",
 "An hour after a buyer leaves checkout without paying, if they asked for news. Turn it on in Checkout.": "Una hora después de que un comprador abandone el pago sin pagar, si pidió novedades. Actívalo en Pago.",
 "An hour after someone presses Pay and no order comes of it. Only people who ticked “Email me news and offers” at checkout, or are on your list, get it, and it stops the moment they buy.": "Una hora después de que alguien pulsa Pagar y no se genera ningún pedido. Solo la reciben quienes marcaron “Envíame noticias y ofertas” al pagar o están en tu lista, y se detiene en cuanto compran.",
 "An icon beside the title": "Un icono junto al título",
 "An image beside the title": "Una imagen junto al título",
 "An image or GIF": "Una imagen o GIF",
 "An integration connects Storelib to a service you already use: Google Analytics, a pixel for your ads, a shipping or print on demand company.": "Una integración conecta Storelib con un servicio que ya usas: Google Analytics, un píxel para tus anuncios, una empresa de envíos o de impresión bajo demanda.",
 "An invite is already an approval, so this only applies to anyone who asks without one.": "Una invitación ya es una aprobación, así que esto solo afecta a quien pide sin ella.",
 "An invite lasts 1 to 365 days.": "Una invitación dura de 1 a 365 días.",
 "An invite link is the only way in.": "Solo se entra con un enlace de invitación.",
 "An order": "Un pedido",
 "An order, a payout, a dispute, your website or something that isn't working. A real person at Storelib reads every one and replies here.": "Un pedido, una transferencia, una disputa, tu sitio web o algo que no funciona. Una persona real de Storelib lee cada mensaje y responde aquí.",
 "An unticked “Email me with news and offers” box under the email. Only buyers who tick it get your campaigns.": "Una casilla sin marcar “Envíame novedades y ofertas” bajo el correo. Solo quienes la marquen reciben tus campañas.",
 "Analytics": "Analíticas",
 "Analytics and pixels": "Analíticas y píxeles",
 "Analytics and pixels need their database update (SQL part 112). Until it runs, nothing here is kept.": "Las analíticas y los píxeles necesitan su actualización de base de datos (parte SQL 112). Hasta entonces, no se guarda nada aquí.",
 "Analytics on this device": "Analíticas en este dispositivo",
