 "Buyers add it for {amount}.": "Los compradores lo añaden por {amount}.",
 "Buyers are asked by email after they buy, on your schedule in Storelib Reviews.": "A los compradores se les pide por correo después de comprar, según tu calendario en Storelib Reviews.",
 "Buyers ask for a return from their order page, and you approve each one.": "Los compradores piden una devolución desde la página de su pedido y tú apruebas cada una.",
 "Buyers can add up to 4 photos. Each one is checked before it is kept.": "Los compradores pueden añadir hasta 4 fotos. Cada una se revisa antes de guardarla.",
 "Buyers can change their review for": "Los compradores pueden cambiar su reseña durante",
 "Buyers can choose it": "Los compradores pueden elegirla",
 "Buyers can collect their order here for free instead of having it shipped.": "Los compradores pueden recoger aquí su pedido gratis en lugar de que se lo envíen.",
 "Buyers can no longer use it. Orders already placed with it keep their discount. To stop it for now instead, turn it off.": "Los compradores ya no podrán usarlo. Los pedidos ya hechos con él mantienen su descuento. Para pausarlo, desactívalo.",
 "Buyers can no longer use it. Orders already placed with it keep their discount. To stop it for now, turn it off instead.": "Los compradores ya no podrán usarlo. Los pedidos ya hechos con él mantienen su descuento. Para pausarlo, desactívalo.",
 "Buyers can still order, and you ship when it's back.": "Los compradores pueden pedir igualmente y envías cuando vuelva.",
 "Buyers can use it at checkout.": "Los compradores pueden usarlo al pagar.",
 "Buyers can't check out a physical product until it has a rate for their address. Add a zone and a rate below.": "Los compradores no pueden pagar un producto físico hasta que tenga una tarifa para su dirección. Añade una zona y una tarifa abajo.",
 "Buyers can't check out on your store yet": "Los compradores aún no pueden pagar en tu tienda",
 "Buyers can't check out until you do.": "Los compradores no pueden pagar hasta que lo hagas.",
 "Buyers can't check out yet": "Los compradores aún no pueden pagar",
 "Buyers can't check out your physical products yet": "Los compradores aún no pueden pagar tus productos físicos",
 "Buyers can't pay at checkout until this is done.": "Los compradores no pueden pagar hasta que esto esté hecho.",
 "Buyers can't pay for anything until this is done.": "Los compradores no pueden pagar nada hasta que esto esté hecho.",
 "Buyers choose Card or Cash on delivery at checkout. The order is placed at once and waits to be sent as usual. Mark it as paid from the order when you have the cash. No Storelib fee is taken on these orders.": "Los compradores eligen Tarjeta o Pago contra reembolso al pagar. El pedido se crea al momento y espera a enviarse como siempre. Márcalo como pagado desde el pedido cuando tengas el efectivo. Storelib no cobra comisión en estos pedidos.",
 "Buyers choose the price": "Los compradores eligen el precio",
 "Buyers choose what to pay, from your minimum.": "Los compradores eligen cuánto pagar, desde tu mínimo.",
 "Buyers create an account or log in before checkout. Signed out visitors can still browse.": "Los compradores crean una cuenta o inician sesión antes de pagar. Los visitantes sin sesión pueden seguir mirando.",
 "Buyers keep their files and their access.": "Los compradores conservan sus archivos y su acceso.",
 "Buyers never see it": "Los compradores nunca lo ven",
 "Buyers only": "Solo compradores",
 "Buyers only see it struck through when it is higher than the price.": "Los compradores solo lo ven tachado cuando es mayor que el precio.",
 "Buyers reply to order emails. Right now replies go to your login email.": "Los compradores responden a los correos de pedidos. Ahora mismo las respuestas van a tu correo de acceso.",
 "Buyers review from their receipt or their library. Storelib asks them a week after they buy on Storelib, and again a week later if they have not.": "Los compradores reseñan desde su recibo o su biblioteca. Storelib se lo pide una semana después de comprar en Storelib, y otra vez una semana más tarde si no lo han hecho.",
 "Buyers see it as sold out. Add stock, or let it keep selling when it runs out.": "Los compradores lo ven agotado. Añade stock o deja que se siga vendiendo cuando se acabe.",
 "Buyers see it when they choose pickup": "Los compradores lo ven al elegir recogida",
 "Buyers see them as sold out. Add stock, or let them keep selling when they run out.": "Los compradores los ven agotados. Añade stock o deja que se sigan vendiendo cuando se acaben.",
 "Buyers see these words on the event page and in their receipt.": "Los compradores ven este texto en la página del evento y en su recibo.",
 "Buyers see “Name a fair price”, starting at your suggested amount.": "Los compradores ven “Pon un precio justo”, empezando por tu importe sugerido.",
 "Buyers watch these in their library, and pick up where they left off.": "Los compradores las ven en su biblioteca y siguen donde lo dejaron.",
 "Buyers who asked to hear from you when they paid.": "Compradores que pidieron recibir noticias tuyas al pagar.",
 "Buyers who choose pickup aren't told when they can come.": "A quienes eligen recogida no se les dice cuándo pueden venir.",
 "Buyers who did not ask for news. They get emails about what they bought, never one you send to your list.": "Compradores que no pidieron noticias. Reciben correos sobre lo que compraron, nunca uno que envíes a tu lista.",
 "Buyers who did not ask, as contacts only": "Compradores que no lo pidieron, solo como contactos",
 "Buyers who did not ask, as profiles only": "Compradores que no lo pidieron, solo como perfiles",
 "Buyers won't be able to check out yet": "Los compradores aún no podrán pagar",
 "Buyers write to it about their orders. The same address your receipts show.": "Los compradores escriben ahí sobre sus pedidos. Es la misma dirección que aparece en tus recibos.",
