 "Checkout": "Pago",
 "Checkout always charges your store's own currency and says so next to the total, so a converted price is shown as an estimate.": "El pago siempre se cobra en la moneda de tu tienda y lo indica junto al total, así que un precio convertido se muestra como estimación.",
 "Checkout canceled. Nothing changed.": "Pago cancelado. No ha cambiado nada.",
 "Checkout charges the visitor's currency, the amounts they saw. A currency Storelib can't charge yet is shown for reference, and checkout says it charges yours.": "El pago cobra en la moneda del visitante, los importes que vio. Una moneda que Storelib aún no puede cobrar se muestra como referencia, y el pago indica que cobra en la tuya.",
 "Checkout charges what your store's prices are in, and says so next to the total, so a converted price is always shown as an estimate.": "El pago cobra en la moneda de los precios de tu tienda y lo indica junto al total, así que un precio convertido siempre se muestra como estimación.",
 "Checkout for the product they left": "Pago del producto que dejaron",
 "Checkout has no way to get an order to the buyer, so nobody can buy.": "El pago no tiene forma de hacer llegar un pedido al comprador, así que nadie puede comprar.",
 "Checkout is closed until payments are set up again, so buyers cannot pay you in the meantime.": "El pago está cerrado hasta que vuelvas a configurar los pagos, así que mientras tanto los compradores no pueden pagarte.",
 "Checkout is the page where a buyer types their details and pays. These settings decide what it asks for.": "El pago es la página donde el comprador escribe sus datos y paga. Estos ajustes deciden qué pide.",
 "Checkout link": "Enlace de pago",
 "Checkout offer": "Oferta en el pago",
