 "Checkout settings": "Ajustes de pago",
 "Checkout settings need their database update (SQL part 109). Until it runs, checkout works as it always has and changes here are not kept.": "La configuración del pago necesita su actualización de base de datos (parte SQL 109). Hasta entonces, el pago funciona como siempre y los cambios aquí no se guardan.",
 "Checks are not running yet on your account, so a flow with a check sends nothing for now. Remove the check to send without it.": "Las comprobaciones aún no funcionan en tu cuenta, así que un flujo con una comprobación no envía nada por ahora. Quita la comprobación para enviar sin ella.",
