 "Downloads, courses and memberships. In the EU, VAT on digital sales is charged at the rate of the buyer's country, so add a region for each country you sell to.": "Descargas, cursos y membresías. En la UE, el IVA de las ventas digitales se cobra al tipo del país del comprador, así que añade una región por cada país al que vendes.",
