 "Due {arrival_date}": "Previsto el {arrival_date}",
 "Duplicate": "Duplicar",
 "Duplicate settings": "Duplicar ajustes",
 "Duplicate {name}": "Duplicar {name}",
 "Dusk": "Anochecer",
 "Dynamic Favicon": "Favicon dinámico",
 "E-books": "E-books",
 "EN": "EN",
 "Each charge lands here with its invoice.": "Cada cargo aparece aquí con su factura.",
 "Each email goes to each person once, however often they trigger it. Someone who unsubscribes gets nothing more.": "Cada correo llega a cada persona una vez, por muchas veces que la active. Quien se da de baja no recibe nada más.",
 "Each hour, text you add or change is translated into your other languages and goes live. Translations you wrote are never replaced.": "Cada hora, el texto que añades o cambias se traduce a tus otros idiomas y se publica. Las traducciones que escribiste nunca se sustituyen.",
 "Each item is priced by its own weight, then added up.": "Cada artículo se cobra por su peso y luego se suma.",
 "Each item pays the price of the step its weight reaches. Two 0.5 {unit} items at a 0 {unit2} step of $3 pay $6.": "Cada artículo paga el precio del tramo que alcanza su peso. Dos artículos de 0,5 {unit} en un tramo de 0 {unit2} de 3 $ pagan 6 $.",
 "Each language gets its own address, like yourstore.com/fr.": "Cada idioma tiene su propia dirección, como yourstore.com/fr.",
 "Each link needs a label and an https:// address.": "Cada enlace necesita un texto y una dirección https://.",
 "Each new order for this location is sent here": "Cada pedido nuevo de esta ubicación se envía aquí",
 "Each new order is sent to your own system as a signed request. Set the address in Integrations.": "Cada pedido nuevo se envía a tu propio sistema como una solicitud firmada. Pon la dirección en Integraciones.",
 "Each new order with items from here is emailed to this partner with the items and the address. You add their tracking number in Orders when they ship.": "Cada pedido nuevo con artículos de aquí se envía por correo a este socio con los artículos y la dirección. Añades su número de seguimiento en Pedidos cuando envíen.",
 "Each order is printed and shipped for you.": "Cada pedido se imprime y se envía por ti.",
 "Each order starts it once. The same order never starts it twice.": "Cada pedido la inicia una vez. El mismo pedido nunca la inicia dos veces.",
 "Each paid order for your CJ location is sent to CJ with the CJ variants you matched, its tracking comes back, and CJ's stock can keep yours in step.": "Cada pedido pagado de tu ubicación de CJ se envía a CJ con las variantes de CJ emparejadas, su seguimiento vuelve y el stock de CJ puede mantener el tuyo al día.",
 "Each paid order for your Gelato location is sent to Gelato with the product and print file you matched, printed near your buyer, and its tracking comes back.": "Cada pedido pagado de tu ubicación de Gelato se envía a Gelato con el producto y el archivo de impresión emparejados, se imprime cerca de tu comprador y su seguimiento vuelve.",
 "Each paid order for your Printful location is sent to your Printful store by SKU, and its tracking comes back to your buyer.": "Cada pedido pagado de tu ubicación de Printful se envía a tu tienda de Printful por SKU, y su seguimiento vuelve a tu comprador.",
 "Each paid order for your Printify location is sent to your Printify shop by SKU, and its tracking comes back to your buyer.": "Cada pedido pagado de tu ubicación de Printify se envía a tu tienda de Printify por SKU, y su seguimiento vuelve a tu comprador.",
 "Each paid order is emailed to the location's supplier with the items and the address. Add tracking when they reply.": "Cada pedido pagado se envía por correo al proveedor de la ubicación con los artículos y la dirección. Añade el seguimiento cuando respondan.",
 "Each paid order is sent to your https address as JSON, signed with your secret (X-Storelib-Signature).": "Cada pedido pagado se envía a tu dirección https como JSON, firmado con tu secreto (X-Storelib-Signature).",
 "Each paid order you ship goes to ShipStation. Print the label there and the tracking comes back to your buyer.": "Cada pedido pagado que envías va a ShipStation. Imprime allí la etiqueta y el seguimiento vuelve a tu comprador.",
 "Each policy is a page of your site, linked from its footer. They start as templates: replace anything in square brackets with your own terms before you publish.": "Cada política es una página de tu sitio, enlazada desde el pie. Empiezan como plantillas: sustituye todo lo que esté entre corchetes por tus propios términos antes de publicar.",
 "Each product page shows its own": "Cada página de producto muestra el suyo",
 "Each product's stock is counted per location. When an order comes in, it is assigned to the default location, and its stock goes down there.": "El stock de cada producto se cuenta por ubicación. Cuando llega un pedido, se asigna a la ubicación predeterminada y su stock baja allí.",
 "Each push arrives within seconds, as a draft. Publish when you like it.": "Cada push llega en segundos, como borrador. Publica cuando te guste.",
 "Each question needs an answer.": "Cada pregunta necesita una respuesta.",
 "Each rule needs a title.": "Cada norma necesita un título.",
 "Each sale becomes available about {settleDays} days after it is paid. That wait is set by our payment partner for your country and protects against refunds and disputes.": "Cada venta está disponible unos {settleDays} días después de pagarse. Esa espera la fija nuestro socio de pagos para tu país y protege frente a reembolsos y disputas.",
 "Each sale becomes available after a short settlement wait set by our payment partner for your country.": "Cada venta está disponible tras una breve espera de liquidación que fija nuestro socio de pagos para tu país.",
 "Each variant has its own quantity, in Variants below.": "Cada variante tiene su propia cantidad, en Variantes abajo.",
