 "In Gelato, Developer › Webhooks, add this address for order status and tracking code updates:": "En Gelato, Developer › Webhooks, añade esta dirección para recibir el estado del pedido y el código de seguimiento:",
 "In Google Analytics, Reports › Realtime shows a visit within a minute. The “Data collection isn't active” notice on your stream can take up to 48 hours to go away.": "En Google Analytics, Informes › Tiempo real muestra una visita en menos de un minuto. El aviso «La recogida de datos no está activa» de tu flujo puede tardar hasta 48 horas en desaparecer.",
