 "Is there a refund policy?": "¿Hay política de reembolso?",
 "Issued once DNS is set": "Se emite cuando el DNS esté configurado",
 "It appears here": "Aparece aquí",
 "It applies only to products in these collections.": "Solo se aplica a productos de estas colecciones.",
 "It applies right away.": "Se aplica al instante.",
 "It arrived damaged": "Llegó dañado",
 "It came in {when}. {amount} so far.": "Llegó {when}. {amount} hasta ahora.",
 "It comes off your page and cannot be brought back.": "Sale de tu página y no se puede recuperar.",
 "It comes off your page. If it has sales it is archived instead, so buyers keep their access.": "Sale de tu página. Si tiene ventas se archiva, así los compradores mantienen el acceso.",
 "It could not be published. Try again.": "No se pudo publicar. Inténtalo de nuevo.",
 "It disappears for everyone. Orders and payments are kept. Not possible while members still pay for it.": "Desaparece para todos. Se conservan los pedidos y los pagos. No es posible mientras haya miembros que paguen por ella.",
 "It goes back to their card in 5 to 10 business days, and your share comes back from your Stripe balance. They get an email.": "Vuelve a su tarjeta en 5 a 10 días hábiles, y tu parte sale de tu saldo de Stripe. Recibe un correo.",
 "It goes live at": "Se publica en",
 "It goes live at {site}.": "Se publica en {site}.",
 "It happened {when}, across {count, plural, one {# sale} other {# sales}}.": "Ocurrió {when}, en {count, plural, one {# venta} other {# ventas}}.",
 "It has not been saved yet, so it will not be kept.": "Aún no se ha guardado, así que no se conservará.",
 "It has not been saved yet, so nothing you added will be kept.": "Aún no se ha guardado, así que no se conservará nada de lo que añadiste.",
 "It has sales, so it will be archived, not deleted. It comes off your page and buyers keep their access.": "Tiene ventas, así que se archivará en lugar de eliminarse. Sale de tu página y los compradores mantienen el acceso.",
 "It has to end after it starts.": "Tiene que terminar después de empezar.",
 "It hasn't arrived": "No ha llegado",
 "It hides before it shows, so it would never be on the page.": "Se oculta antes de mostrarse, así que nunca estaría en la página.",
 "It is a draft. Only you can see it until you publish.": "Es un borrador. Solo tú puedes verla hasta que la publiques.",
 "It is gone for good, with its photos. To take it off your store and keep it, hide it instead.": "Desaparece para siempre, con sus fotos. Para quitarla de tu tienda y conservarla, ocúltala.",
 "It is hidden from your product page and its rating now. Storelib reads it and either brings it back or keeps it hidden.": "Ya está oculta en tu página de producto y en su valoración. Storelib la lee y la recupera o la mantiene oculta.",
 "It is not a Storelib product and is not listed anywhere else.": "No es un producto de Storelib ni aparece en ningún otro sitio.",
 "It is not connected yet, so nothing stops working.": "Aún no está conectado, así que nada deja de funcionar.",
 "It is off until you turn it on.": "Está desactivada hasta que la actives.",
 "It is removed from Messages. The email you got about it stays in your inbox, and the sender stays in your contacts.": "Se quita de Mensajes. El correo que recibiste sobre él sigue en tu bandeja, y el remitente sigue en tus contactos.",
 "It is removed with its numbers. Anything already sent stays in people's inboxes.": "Se elimina con sus cifras. Lo ya enviado sigue en las bandejas de entrada.",
 "It is yours": "Ya es tuyo",
 "It may have been deleted. Go back to your websites.": "Puede que se haya eliminado. Vuelve a tus sitios web.",
 "It opens soon": "Se abre pronto",
 "It plays on your page in the YouTube or Vimeo player.": "Se reproduce en tu página con el reproductor de YouTube o Vimeo.",
 "It reads Payment pending until you press Mark as paid on the order, once you have the cash. A parcel the buyer refuses: press Refused on delivery. Nothing is refunded, and what was sent comes back as a return.": "Indica Pago pendiente hasta que pulses Marcar como pagado en el pedido, cuando tengas el efectivo. Un paquete que el comprador rechaza: pulsa Rechazado en la entrega. No se reembolsa nada y lo enviado vuelve como devolución.",
 "It replaces “{name}” at": "Reemplaza a “{name}” en",
 "It replaces “{name}” at {site}. Nothing is deleted.": "Sustituye a “{name}” en {site}. No se elimina nada.",
 "It shows as cancelled to members, and anyone going hears about it. You can put it back on.": "Se muestra como cancelado a los miembros y se avisa a quienes iban a ir. Puedes volver a ponerlo.",
 "It starts as a draft. Add its lessons, then publish it.": "Empieza como borrador. Añade sus lecciones y luego publícalo.",
 "It stops at once for everyone partway through, and its history goes with it.": "Se detiene al instante para todos los que estén a mitad, y su historial desaparece con ella.",
 "It takes nothing off downloads or courses in the same cart.": "No descuenta nada de descargas ni cursos del mismo carrito.",
 "It usually arrives in 1 to 3 business days.": "Suele llegar en 1 a 3 días hábiles.",
 "It was already sent to your print partner. Cancel it there too.": "Ya se envió a tu socio de impresión. Cancélalo también allí.",
 "It was archived instead": "Se archivó en su lugar",
 "It was deleted. The email you got about it is still in your inbox.": "Se eliminó. El correo que recibiste sobre él sigue en tu bandeja.",
 "It was used, or it's past the return window.": "Se usó o ya pasó el plazo de devolución.",
 "It's a passport": "Es un pasaporte",
 "It's here": "Ya está aquí",
 "It's kept as a draft, so the title and photos can wait. You come back to it here.": "Se guarda como borrador, así que el título y las fotos pueden esperar. Vuelves a él desde aquí.",
