 "Member status": "Estado del miembro",
 "Members": "Miembros",
 "Members are told about announcements.": "Los miembros reciben aviso de los anuncios.",
 "Members can comment on posts here.": "Los miembros pueden comentar las publicaciones aquí.",
 "Members can read it; nobody can post. Bringing it back makes it a draft.": "Los miembros pueden leerla; nadie puede publicar. Recuperarla la convierte en borrador.",
 "Members can see who else is here.": "Los miembros pueden ver quién más está aquí.",
 "Members can still read it. Nobody can post or join until you bring it back. Nothing is deleted.": "Los miembros aún pueden leerla. Nadie puede publicar ni unirse hasta que la recuperes. No se borra nada.",
 "Members earn points when their posts and comments get reactions, and climb levels. A leaderboard shows in the community.": "Los miembros ganan puntos cuando sus publicaciones y comentarios reciben reacciones, y suben de nivel. Se muestra una clasificación en la comunidad.",
 "Members get these in their library while their membership lasts.": "Los miembros los tienen en su biblioteca mientras dure su membresía.",
 "Members now": "Miembros ahora",
 "Members on {name}": "Miembros de {name}",
 "Members pay for a tier to join.": "Los miembros pagan un nivel para unirse.",
 "Members pay monthly or yearly to join your community.": "Los miembros pagan mensual o anualmente para unirse a tu comunidad.",
 "Members pay once, in a checkout inside the community. ": "Los miembros pagan una vez, en un pago dentro de la comunidad. ",
 "Members pay once, in a checkout inside the community. The meeting link, the address and who else is going open when they have a ticket.": "Los miembros pagan una vez, en un pago dentro de la comunidad. El enlace de la reunión, la dirección y quién más va se muestran cuando tienen entrada.",
 "Members pay through Stripe. You can add a yearly price or more tiers later.": "Los miembros pagan con Stripe. Puedes añadir un precio anual o más niveles después.",
 "Members pay to join, every month, every year or once.": "Los miembros pagan por unirse, cada mes, cada año o una vez.",
 "Members pay you through Stripe. Nobody can join a paid community until payouts are connected.": "Los miembros te pagan con Stripe. Nadie puede unirse a una comunidad de pago hasta que conectes las transferencias.",
 "Members pay {amount} once, in a checkout inside the community. ": "Los miembros pagan {amount} una vez, en un pago dentro de la comunidad. ",
 "Members pay {priceText}.": "Los miembros pagan {priceText}.",
 "Members paying now, including anyone whose card is being retried. Somebody who cancelled keeps access until their period ends and is not counted.": "Miembros que pagan ahora, incluido quien tiene la tarjeta en reintento. Quien canceló mantiene el acceso hasta que termine su periodo y no se cuenta.",
 "Members post": "Publican los miembros",
 "Members reach levels by taking part. Below it, they see the program with the level it opens at.": "Los miembros alcanzan niveles participando. Por debajo, ven el programa con el nivel en que se abre.",
 "Members see it under Learn.": "Los miembros lo ven en Aprender.",
 "Members see posts on their membership page. Put the membership on sale in Settings to let people join.": "Los miembros ven las publicaciones en su página de membresía. Pon la membresía a la venta en Ajustes para que la gente se una.",
 "Members see them before they join and when they post.": "Los miembros las ven antes de unirse y al publicar.",
 "Members stop seeing it here. The course and its buyers are not touched.": "Los miembros dejan de verlo aquí. El curso y sus compradores no se tocan.",
 "Members stop seeing it in the classroom. The course and its buyers are not touched.": "Los miembros dejan de verlo en el aula. El curso y sus compradores no se tocan.",
 "Members stop seeing it, and every open report about it is closed. You can restore it from the Feed.": "Los miembros dejan de verlo y se cierran todas sus denuncias abiertas. Puedes restaurarlo desde el Feed.",
 "Members stop seeing it. You can restore it from Removed.": "Los miembros dejan de verla. Puedes restaurarla desde Eliminadas.",
 "Members who could attend can watch it on the event page afterwards.": "Los miembros que podían asistir pueden verla después en la página del evento.",
 "Members who have it lose it.": "Los miembros que la tienen la pierden.",
 "Members write to you from the community. Messages reach your inbox and this email; it stays private unless you show it.": "Los miembros te escriben desde la comunidad. Los mensajes llegan a tu bandeja y a este correo; es privado salvo que lo muestres.",
