 "Once it is available you can cash it out, and it usually reaches your bank in 1 to 3 business days.": "Cuando está disponible puedes retirarla, y suele llegar a tu banco en 1 a 3 días hábiles.",
 "Once it starts it cannot be taken back. You can stop the ones not yet sent.": "Una vez que empieza no se puede deshacer. Puedes detener los que aún no se han enviado.",
 "Once per person": "Una vez por persona",
 "Once saved, they'll appear on your OnePage.": "Una vez guardados, aparecerán en tu OnePage.",
 "Once the items are back, mark them received: you choose whether they go back into stock, and you refund the buyer from the same screen.": "Cuando vuelvan los artículos, márcalos como recibidos: eliges si vuelven al stock y reembolsas al comprador desde la misma pantalla.",
 "One a line, for example\nfree followers\ncrypto signal*": "Una por línea, por ejemplo\nseguidores gratis\nseñal cripto*",
 "One email a day at most, listing what sold down to its low stock line.": "Como mucho un correo al día, con lo que bajó hasta su umbral.",
 "One email an hour later with a link back to what they chose, only to buyers who ticked the news box. It stops the moment they buy.": "Un correo una hora después con un enlace a lo que eligió, solo a quienes marcaron la casilla de novedades. Se detiene en cuanto compran.",
 "One email an hour later, only to buyers who ticked the news box. With the news box hidden nobody can tick it, so no reminder goes out.": "Un correo una hora después, solo a quienes marcaron la casilla de novedades. Con la casilla oculta nadie puede marcarla, así que no se envía ningún recordatorio.",
 "One event has a price, and nobody can buy a ticket until payouts are connected.": "Un evento tiene precio y nadie puede comprar entrada hasta que conectes las transferencias.",
