 "Store details": "Datos de la tienda",
 "Store details need their database update (SQL part 109). Until it runs, what you see here is not saved.": "Los datos de la tienda necesitan su actualización de base de datos (parte SQL 109). Hasta entonces, lo que ves aquí no se guarda.",
 "Store is unpublished. Go to Settings to publish.": "La tienda no está publicada. Ve a Ajustes para publicarla.",
 "Store name": "Nombre de la tienda",
