 "Store setup guide": "Guía para configurar tu tienda",
 "Store setup, {setupProgressPercent}% done": "Configuración de la tienda, {setupProgressPercent} % hecho",
 "Stored encrypted and never shown again.": "Se guarda cifrada y nunca se vuelve a mostrar.",
 "Storelib AI": "Storelib AI",
 "Storelib AI could not be reached. Check your connection and try again.": "No se pudo contactar con Storelib AI. Revisa tu conexión e inténtalo de nuevo.",
 "Storelib AI is already included in your plan. Connect your own Claude or OpenAI API key to use your account for that provider without counting those edits against your plan.": "Storelib AI ya está incluido en tu plan. Conecta tu propia clave de API de Claude u OpenAI para usar tu cuenta de ese proveedor sin que esas ediciones cuenten para tu plan.",
 "Storelib AI is already included in your plan. If you would rather it ran on your own OpenAI key, connect it here and those edits stop counting against your plan's AI edits.": "Storelib AI ya está incluido en tu plan. Si prefieres que funcione con tu propia clave de OpenAI, conéctala aquí y esas ediciones dejarán de contar para las ediciones de IA de tu plan.",
 "Storelib AI is busy right now. Try again in a moment.": "Storelib AI está ocupado ahora mismo. Inténtalo de nuevo en un momento.",
 "Storelib AI isn't available right now. You can still translate each text yourself.": "Storelib AI no está disponible ahora mismo. Puedes traducir cada texto tú mismo.",
 "Storelib AI now answers on your account. Your key is used for your chats only, kept encrypted, and never shown again.": "Storelib AI ahora responde con tu cuenta. Tu clave se usa solo para tus chats, se guarda cifrada y nunca se vuelve a mostrar.",
 "Storelib AI reads these before every change on every one of your websites. Tell it “remember this” in the builder, or add one here.": "Storelib AI lee esto antes de cada cambio en todos tus sitios web. Dile “recuerda esto” en el editor o añádelo aquí.",
 "Storelib Help Center": "Centro de ayuda de Storelib",
 "Storelib Payments": "Storelib Payments",
 "Storelib Reviews is on": "Storelib Reviews está activado",
 "Storelib Reviews needs its database update (SQL part 134). Until it runs, nothing here is kept.": "Storelib Reviews necesita su actualización de base de datos (parte SQL 134). Hasta entonces, no se guarda nada aquí.",
 "Storelib address": "Dirección de Storelib",
 "Storelib adds the package's empty weight to the products inside when it works out a weight based shipping rate, so the buyer pays for what the parcel really weighs.": "Storelib suma el peso vacío del paquete a los productos de dentro al calcular una tarifa por peso, para que el comprador pague lo que realmente pesa el envío.",
 "Storelib apps": "Apps de Storelib",
 "Storelib apps and the services you already use.": "Apps de Storelib y los servicios que ya usas.",
 "Storelib badge hidden": "Insignia de Storelib oculta",
 "Storelib badge shown": "Insignia de Storelib visible",
 "Storelib can't reach your repository": "Storelib no puede acceder a tu repositorio",
 "Storelib can't take card payments in {local} yet, so your store sells in {currency}.": "Storelib aún no puede cobrar con tarjeta en {local}, así que tu tienda vende en {currency}.",
 "Storelib cannot see any repositories. Give it access to one on GitHub, then": "Storelib no ve ningún repositorio. Dale acceso a uno en GitHub y luego",
 "Storelib charges what you set and nothing more. Ask an accountant which rates apply to you.": "Storelib cobra lo que configures y nada más. Pregunta a un asesor qué tipos se te aplican.",
 "Storelib charges what you set here and nothing more. Check which rates apply to you with an accountant.": "Storelib cobra lo que configures aquí y nada más. Consulta con un asesor qué tipos se te aplican.",
 "Storelib couldn't open your site to take the push": "Storelib no pudo abrir tu sitio para recibir el push",
 "Storelib couldn't sign in to your repository. Reconnect GitHub and try again. Nothing on your site was lost.": "Storelib no pudo entrar en tu repositorio. Vuelve a conectar GitHub e inténtalo de nuevo. No se perdió nada de tu sitio.",
 "Storelib didn't answer": "Storelib no respondió",
 "Storelib doesn't take changes to this file": "Storelib no acepta cambios en este archivo",
 "Storelib fee": "Comisión de Storelib",
 "Storelib includes it in the answer to the bank.": "Storelib lo incluye en la respuesta al banco.",
 "Storelib is answering the bank. Add anything that proves the sale so it can be sent with the response.": "Storelib está respondiendo al banco. Añade cualquier cosa que demuestre la venta para enviarla con la respuesta.",
 "Storelib is helping with this case. Its messages go to you and the buyer.": "Storelib está ayudando con este caso. Sus mensajes os llegan a ti y al comprador.",
 "Storelib is not allowed to use the microphone. Allow Microphone in Storelib's app permissions, then try again.": "Storelib no tiene permiso para usar el micrófono. Permite el micrófono en los permisos de la app de Storelib e inténtalo de nuevo.",
 "Storelib is not allowed to use the microphone. Turn on Microphone for Storelib in Settings, then try again.": "Storelib no tiene permiso para usar el micrófono. Activa Micrófono para Storelib en Ajustes e inténtalo de nuevo.",
 "Storelib news": "Novedades de Storelib",
 "Storelib news emails": "correos de novedades de Storelib",
 "Storelib newsletter": "Boletín de Storelib",
 "Storelib profile": "Perfil de Storelib",
 "Storelib support": "Soporte de Storelib",
 "Storelib suspended this community. Members cannot open it. Contact support to talk about it.": "Storelib suspendió esta comunidad. Los miembros no pueden abrirla. Contacta con soporte para hablarlo.",
 "Storelib took this community out of Explore. Contact support to talk about it.": "Storelib retiró esta comunidad de Explorar. Contacta con soporte para hablarlo.",
 "Storelib was just updated. Refresh the page and try again.": "Storelib se acaba de actualizar. Recarga la página e inténtalo de nuevo.",
 "Storelib will look at the case and write to you both.": "Storelib revisará el caso y os escribirá a ambos.",
 "Storelib writes this website's whole theme into it: settings, pages, header and footer, sections and blocks, with an AGENTS.md your tool reads first.": "Storelib escribe en él todo el tema de este sitio web: ajustes, páginas, cabecera y pie, secciones y bloques, con un AGENTS.md que tu herramienta lee primero.",
 "Storelib's fee for your plan ({freeFee} on Free, {proFee} on Pro), and Stripe's card processing fee, which Stripe charges on every plan. There is nothing else.": "La comisión de Storelib según tu plan ({freeFee} en Gratis, {proFee} en Pro) y la comisión de procesamiento de tarjeta de Stripe, que Stripe cobra en todos los planes. No hay nada más.",
 "Storelib, automatically": "Storelib, automáticamente",
