 "Visitor currencies": "Monedas para visitantes",
 "Visitors": "Visitantes",
 "Visitors are matched by the country they browse from, and can change it with the currency or country selector. Their choice is remembered.": "Los visitantes se asignan por el país desde el que navegan y pueden cambiarlo con el selector de moneda o país. Su elección se recuerda.",
 "Visitors are matched by the country they browse from, and can change it with the currency selector. Their choice is remembered.": "Los visitantes se asignan por el país desde el que navegan y pueden cambiarlo con el selector de moneda. Su elección se recuerda.",
 "Visitors confirm before it opens": "Los visitantes confirman antes de abrirlo",
 "Visitors go to {goesTo} for 30 days, then it stops.": "Los visitantes van a {goesTo} durante 30 días y después se detiene.",
 "Visitors in the EU, the UK and Switzerland are counted in full once they accept cookies; before that Google gets a cookieless ping.": "Los visitantes de la UE, el Reino Unido y Suiza se cuentan del todo cuando aceptan las cookies; antes, Google recibe un ping sin cookies.",
 "Visitors may see a different order depending on their location or preferences.": "Los visitantes pueden ver otro orden según su ubicación o preferencias.",
 "Visitors see a placeholder until you publish again.": "Los visitantes verán una página de espera hasta que vuelvas a publicar.",
 "Visitors see a placeholder. {name} was the last one live.": "Los visitantes ven una página de espera. {name} fue el último publicado.",
 "Visitors see it once {title} is published in Products › Collections.": "Los visitantes la verán cuando {title} esté publicada en Productos › Colecciones.",
 "Visitors see the last version you published.": "Los visitantes ven la última versión que publicaste.",
 "Visitors see this once {name} is published and public.": "Los visitantes la verán cuando {name} esté publicada y sea pública.",
 "Visitors see your password page until they type the password.": "Los visitantes ven tu página de contraseña hasta que escriben la contraseña.",
 "Visitors start in": "Los visitantes empiezan en",
 "Visitors switch with the language selector. On a Storelib theme it sits under the footer by itself. On a theme you imported from Shopify it is the theme's own selector, turned on in the editor (Show language, usually in the header or footer).": "Los visitantes cambian con el selector de idioma. En un tema de Storelib está bajo el pie, solo. En un tema importado de Shopify es el selector del propio tema, activado en el editor (Show language, normalmente en la cabecera o el pie).",
 "Visitors switch with your theme's language selector. Turn on Show visitors their own language to open a first visit in their browser's language.": "Los visitantes cambian con el selector de idioma de tu tema. Activa Mostrar a los visitantes su propio idioma para abrir la primera visita en el idioma de su navegador.",
 "Voice input cannot hear this language here. Type it instead.": "La entrada de voz no entiende este idioma aquí. Escríbelo.",
 "Voice input needs a connection. Check it and try again.": "La entrada de voz necesita conexión. Revísala e inténtalo de nuevo.",
 "Voice input stopped before it heard anything. Try again, or type it.": "La entrada de voz se detuvo antes de oír nada. Inténtalo de nuevo o escríbelo.",
 "Void label": "Anular etiqueta",
