 "What you wrote in this email is replaced.": "Se sustituye lo que escribiste en este correo.",
 "What your buyers get from you, and when. Open one to see it and change its words. Each goes out with your store's name, and a reply comes to your contact email.": "Lo que reciben tus compradores y cuándo. Abre uno para verlo y cambiar su texto. Cada uno se envía con el nombre de tu tienda y las respuestas llegan a tu correo de contacto.",
