 "When": "Cuándo",
 "When a buyer asks to return items, so they know it arrived.": "Cuando un comprador pide devolver artículos, para que sepa que llegó.",
 "When a buyer has a problem with an order (it hasn't arrived, it came damaged, they want a refund), they ask from their order page and it lands here and in your email. You answer first; either of you can ask Storelib to step in.": "Cuando un comprador tiene un problema con un pedido (no llegó, llegó dañado, quiere un reembolso), lo pide desde la página de su pedido y llega aquí y a tu correo. Respondes tú primero; cualquiera de los dos puede pedir a Storelib que intervenga.",
 "When a draft was last changed.": "Cuándo se cambió un borrador por última vez.",
 "When a review comes in": "Cuando llega una reseña",
 "When a shipment is marked as failed: the carrier, or your own delivery, couldn't deliver it.": "Cuando un envío se marca como fallido: el transportista, o tu propia entrega, no pudo entregarlo.",
 "When a store's owner invites you, it shows here and you can open it from your own account.": "Cuando el propietario de una tienda te invite, aparecerá aquí y podrás abrirla desde tu cuenta.",
 "When buyers can come. Shown at checkout and in the pickup email.": "Cuándo pueden venir los compradores. Se muestra en el pago y en el correo de recogida.",
 "When does Pro pay for itself?": "¿Cuándo se paga solo Pro?",
 "When it pushes to": "Cuando haga push a",
