 "When it's marked delivered.": "Cuando se marca como entregado.",
 "When members leave they can say why. Their answers show up here.": "Cuando los miembros se van, pueden decir por qué. Sus respuestas aparecen aquí.",
 "When members report a post, a comment or somebody, it lands here.": "Cuando los miembros denuncian una publicación, un comentario o a alguien, llega aquí.",
 "When pressed": "Al pulsar",
 "When returns are on, a buyer sees Request a return on their order page for as many days as your return window.": "Con las devoluciones activadas, el comprador ve Solicitar una devolución en la página de su pedido durante los días de tu plazo de devolución.",
 "When somebody writes to you through the contact form on your website, the message shows here and in your email.": "Cuando alguien te escribe desde el formulario de contacto de tu sitio web, el mensaje aparece aquí y en tu correo.",
