 "Wins": "Logros",
 "With Show visitors their own language on, a first visit opens in the published language the browser asks for, once. A close match, or only the country to go by, gets a small offer on the page instead. A market can also start its countries in its own language. After that the visitor's choice wins, and search engines still see every language at its own address.": "Con «Mostrar a los visitantes su idioma» activado, una primera visita se abre una vez en el idioma publicado que pide el navegador. Si solo se parece, o solo se conoce el país, aparece una pequeña sugerencia en la página. Un mercado también puede abrir sus países en su propio idioma. Después manda la elección del visitante, y los buscadores siguen viendo cada idioma en su propia dirección.",
